#include <immintrin.h>
int64_t sum_simd(const int32_t* a, size_t n) {
    __m256i acc = _mm256_setzero_si256();  // 8 lanes of int32
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        __m256i v = _mm256_loadu_si256((const __m256i*)(a + i));
        acc = _mm256_add_epi32(acc, v);
    }
    // horizontal reduce: 8 lanes -> 1 scalar
    int32_t lanes[8]; _mm256_storeu_si256((__m256i*)lanes, acc);
    int64_t s = 0;
    for (int k = 0; k < 8; ++k) s += lanes[k];
    for (; i < n; ++i) s += a[i];
    return s;
}

