# Python: class decorator that adds a constructor
def with_default_init(cls):
    fields = [k for k in vars(cls) if not k.startswith('_') and not callable(vars(cls)[k])]
    defaults = {k: vars(cls)[k] for k in fields}
    def __init__(self, **kwargs):
        for k, v in defaults.items():
            setattr(self, k, kwargs.get(k, v))
    cls.__init__ = __init__
    return cls

