# Catalan numbers via Dyck-path enumeration
def catalan_dyck(n):
    # Number of Dyck paths of length 2n: nonneg lattice paths (0,0)->(n,n) staying weakly below the diagonal
    # Closed form via reflection principle: C(2n,n)/(n+1)
    from math import comb
    return comb(2*n, n) // (n + 1)

def enumerate_dyck_paths(n):
    # Generate all Dyck words: sequences of n 'U's and n 'D's, never going below zero in prefix sum
    def rec(ups_left, downs_left, height):
        if ups_left == 0 and downs_left == 0: yield ''; return
        if ups_left > 0:
            for tail in rec(ups_left - 1, downs_left, height + 1): yield 'U' + tail
        if downs_left > 0 and height > 0:
            for tail in rec(ups_left, downs_left - 1, height - 1): yield 'D' + tail
    return list(rec(n, n, 0))

