# Classical inclusion-exclusion on n sets
from itertools import combinations
def inclusion_exclusion(sets):
    n = len(sets); universe_size = 0
    for k in range(1, n+1):
        for combo in combinations(range(n), k):
            inter = set.intersection(*(sets[i] for i in combo))
            universe_size += (-1)**(k+1) * len(inter)
    return universe_size
# Computes |union A_i| in 2^n - 1 terms; alternating signs by subset size

