# Mobius inversion on a poset (general framework)
def mobius_function(poset, x, y):
    # mu(x,x) = 1; mu(x,y) = -sum_{x <= z < y} mu(x,z) for x < y
    if x == y: return 1
    if not poset.le(x, y): return 0
    return -sum(mobius_function(poset, x, z) for z in poset.interval(x, y) if z != y)

def mobius_inversion(poset, g):
    # If g(t) = sum_{s <= t} f(s), then f(t) = sum_{s <= t} mu(s, t) g(s)
    return lambda t: sum(mobius_function(poset, s, t) * g(s) for s in poset.below(t))

