import heapq
from collections import Counter
def huffman(s: str) -> str:
    freq = Counter(s)
    heap = [[w, [sym, '']] for sym, w in freq.items()]
    heapq.heapify(heap)
    while len(heap) > 1:
        lo = heapq.heappop(heap); hi = heapq.heappop(heap)
        for p in lo[1:]: p[1] = '0' + p[1]
        for p in hi[1:]: p[1] = '1' + p[1]
        heapq.heappush(heap, [lo[0]+hi[0]] + lo[1:] + hi[1:])
    codes = {sym: code for sym, code in heap[0][1:]}
    return ''.join(codes[c] for c in s)

def lz77_encode(s: bytes, window: int = 4096, lookahead: int = 18) -> list:
    out = []
    i = 0
    while i < len(s):
        best_len, best_dist = 0, 0
        start = max(0, i - window)
        for d in range(start, i):
            ln = 0
            while ln < lookahead and i + ln < len(s) and s[d + ln] == s[i + ln]:
                ln += 1
            if ln > best_len:
                best_len, best_dist = ln, i - d
        next_char = s[i + best_len] if i + best_len < len(s) else 0
        out.append((best_dist, best_len, next_char))
        i += best_len + 1
    return out  # list of (dist, len, next_char) triples

