def lzss_encode(s: bytes, window: int = 4096, lookahead: int = 18, min_match: int = 3) -> list:
    out = []
    i = 0
    while i < len(s):
        best_len, best_dist = 0, 0
        start = max(0, i - window)
        for d in range(start, i):
            ln = 0
            while ln < lookahead and i + ln < len(s) and s[d + ln] == s[i + ln]:
                ln += 1
            if ln > best_len:
                best_len, best_dist = ln, i - d
        if best_len >= min_match:
            out.append(('M', best_dist, best_len))
            i += best_len
        else:
            out.append(('L', s[i]))
            i += 1
    return out  # list of ('L', byte) literals or ('M', dist, len) matches

