def shannon_fano(freq: dict) -> dict:
    items = sorted(freq.items(), key=lambda x: -x[1])
    codes = {sym: '' for sym, _ in items}
    def split(lo, hi):
        if hi - lo <= 1: return
        total = sum(freq[items[i][0]] for i in range(lo, hi))
        running = 0; mid = lo
        for i in range(lo, hi):
            running += freq[items[i][0]]
            if running >= total / 2:
                mid = i + 1; break
        for i in range(lo, mid): codes[items[i][0]] += '0'
        for i in range(mid, hi): codes[items[i][0]] += '1'
        split(lo, mid); split(mid, hi)
    split(0, len(items))
    return codes

