# Direct conv2d: 6-loop nest, cache-unfriendly
import numpy as np
def conv2d_direct(x, w):  # x: (C, H, W), w: (F, C, KH, KW)
    C, H, W = x.shape
    F, _, KH, KW = w.shape
    OH, OW = H - KH + 1, W - KW + 1
    y = np.zeros((F, OH, OW))
    for f in range(F):
      for c in range(C):
        for i in range(OH):
          for j in range(OW):
            for kh in range(KH):
              for kw in range(KW):
                y[f, i, j] += x[c, i+kh, j+kw] * w[f, c, kh, kw]
    return y

