float dot_simd(const float* a, const float* b, size_t n) {
    __m256 acc = _mm256_setzero_ps();  // 8 lanes of float32
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        __m256 va = _mm256_loadu_ps(a + i);
        __m256 vb = _mm256_loadu_ps(b + i);
        acc = _mm256_fmadd_ps(va, vb, acc);   // acc += va*vb, single rounding
    }
    // horizontal reduce: 8 lanes -> 1 scalar (tree-pairwise)
    __m128 lo = _mm256_castps256_ps128(acc);
    __m128 hi = _mm256_extractf128_ps(acc, 1);
    __m128 s4 = _mm_add_ps(lo, hi);              // 4 partial sums
    s4 = _mm_hadd_ps(s4, s4); s4 = _mm_hadd_ps(s4, s4);
    float s; _mm_store_ss(&s, s4);
    for (; i < n; ++i) s += a[i] * b[i];          // scalar tail
    return s;
}

