def astar_zero_heuristic(graph, source):
    import heapq
    # A* with heuristic h(v) == 0 is exactly Dijkstra. We compute single-source
    # all-targets distances by never popping a goal early.
    def h(v):
        return 0
    g_score = {source: 0}
    open_set = [(0 + h(source), source)]
    while open_set:
        _, u = heapq.heappop(open_set)
        du = g_score.get(u, float('inf'))
        for v, w in graph.get(u, []):
            nd = du + w
            if nd < g_score.get(v, float('inf')):
                g_score[v] = nd
                heapq.heappush(open_set, (nd + h(v), v))
    return g_score

