def floyd_warshall(graph):
    nodes = sorted(set(list(graph.keys()) + [v for adj in graph.values() for v, _ in adj]))
    idx = {n: i for i, n in enumerate(nodes)}
    N = len(nodes)
    INF = float('inf')
    D = [[INF] * N for _ in range(N)]
    for i in range(N):
        D[i][i] = 0
    for u, adj in graph.items():
        for v, w in adj:
            if w < D[idx[u]][idx[v]]:
                D[idx[u]][idx[v]] = w
    for k in range(N):
        for i in range(N):
            dik = D[i][k]
            if dik == INF:
                continue
            for j in range(N):
                nd = dik + D[k][j]
                if nd < D[i][j]:
                    D[i][j] = nd
    return {(nodes[i], nodes[j]): D[i][j]
            for i in range(N) for j in range(N) if D[i][j] != INF}

