def ford_fulkerson(graph, source, sink):
    # Generic Ford-Fulkerson with DFS-based augmenting-path search.
    # Builds a residual graph and augments until no more s->t path exists.
    from collections import defaultdict
    residual = defaultdict(lambda: defaultdict(int))
    for u, adj in graph.items():
        for v, c in adj.items():
            residual[u][v] += c
    def dfs_find(s, t, visited):
        if s == t:
            return [s]
        visited.add(s)
        for v, c in list(residual[s].items()):
            if v not in visited and c > 0:
                path = dfs_find(v, t, visited)
                if path is not None:
                    return [s] + path
        return None
    total_flow = 0
    while True:
        path = dfs_find(source, sink, set())
        if path is None:
            break
        bn = min(residual[path[i]][path[i+1]] for i in range(len(path)-1))
        for i in range(len(path)-1):
            residual[path[i]][path[i+1]] -= bn
            residual[path[i+1]][path[i]] += bn
        total_flow += bn
    return total_flow

