def prim_mst(graph):
    import heapq
    nodes = set(graph.keys())
    for adj in graph.values():
        for v, _ in adj:
            nodes.add(v)
    if not nodes:
        return 0.0
    start = min(nodes)
    in_tree = {start}
    pq = []
    for v, w in graph.get(start, []):
        heapq.heappush(pq, (w, start, v))
    total = 0.0
    while pq and len(in_tree) < len(nodes):
        w, u, v = heapq.heappop(pq)
        if v in in_tree:
            continue
        in_tree.add(v)
        total += w
        for x, wx in graph.get(v, []):
            if x not in in_tree:
                heapq.heappush(pq, (wx, v, x))
    return total

