def kruskal_mst(graph):
    nodes = set(graph.keys())
    edges = set()
    for u, adj in graph.items():
        nodes.add(u)
        for v, w in adj:
            nodes.add(v)
            a, b = (u, v) if u <= v else (v, u)
            edges.add((a, b, w))
    edges = sorted(edges, key=lambda e: e[2])
    parent = {n: n for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        parent[ra] = rb
        return True
    total = 0.0
    for u, v, w in edges:
        if union(u, v):
            total += w
    return total

