def tarjan_scc(graph):
    import sys
    sys.setrecursionlimit(10000)
    index_counter = [0]
    stack = []
    on_stack = {}
    index = {}
    lowlink = {}
    sccs = []
    def strongconnect(v):
        index[v] = index_counter[0]
        lowlink[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack[v] = True
        for w in graph.get(v, []):
            if w not in index:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack.get(w):
                lowlink[v] = min(lowlink[v], index[w])
        if lowlink[v] == index[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            sccs.append(frozenset(scc))
    nodes = set(graph.keys())
    for adj in graph.values():
        for x in adj:
            nodes.add(x)
    for v in sorted(nodes):
        if v not in index:
            strongconnect(v)
    return frozenset(sccs)

