# Naive triple-loop matmul
import numpy as np
def matmul_naive(A, B):
    m, k = A.shape; _, n = B.shape
    C = np.zeros((m, n))
    for i in range(m):
        for j in range(n):
            for kk in range(k):
                C[i, j] += A[i, kk] * B[kk, j]
    return C

