# Cache-blocked matmul
import numpy as np
def matmul_blocked(A, B, block=32):
    m, k = A.shape; _, n = B.shape
    C = np.zeros((m, n))
    for ii in range(0, m, block):
        for jj in range(0, n, block):
            for kk in range(0, k, block):
                # work on a block-sized tile that fits in L1
                C[ii:ii+block, jj:jj+block] += (
                    A[ii:ii+block, kk:kk+block] @ B[kk:kk+block, jj:jj+block]
                )
    return C

