import numpy as np
def kron_loop(A, B):
    m, n = A.shape; p, q = B.shape
    K = np.zeros((m * p, n * q), dtype=np.result_type(A, B))
    for i in range(m):
        for j in range(n):
            for k in range(p):
                for l in range(q):
                    K[i * p + k, j * q + l] = A[i, j] * B[k, l]
    return K

