# Rank via column-pivoted QR (cheap but heuristic)
import numpy as np
import scipy.linalg as la
def rank_qr(A, tol=None):
    Q, R, piv = la.qr(A, pivoting=True)
    diag = np.abs(np.diag(R))
    if tol is None:
        tol = diag.max() * max(A.shape) * np.finfo(A.dtype).eps
    return int((diag > tol).sum())

