def rank_svd(A, tol=None):
    s = np.linalg.svd(A, compute_uv=False)   # singular values, sorted desc
    if tol is None:
        tol = s.max() * max(A.shape) * np.finfo(A.dtype).eps
    return int((s > tol).sum())

