# Treiber's stack (1986) — exactly the canonical form, plus hazard pointers for safe reclaim
class TreiberStack:
    def push(self, v):
        new = Node(v)
        while True:
            top = self.top.load(ACQ)
            new.next = top
            if self.top.compare_exchange_weak(top, new, REL, RLX): return

    def pop(self):
        while True:
            top = self.top.load(ACQ)
            if top is None: return None
            hp.protect(top)              # hazard-pointer to guard against ABA + reclaim
            if self.top.load(ACQ) != top: continue
            nxt = top.next
            if self.top.compare_exchange_weak(top, nxt, ACQ_REL, RLX):
                hp.retire(top); return top.value

