// naive triple loop: O(N^3), O(N^3) memory traffic — cache-hostile
void matmul_naive(const float* A, const float* B, float* C, int N) {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            float s = 0;
            for (int k = 0; k < N; ++k) s += A[i*N+k] * B[k*N+j];
            C[i*N+j] = s;
        }
}

target_form:
// blocked / tiled: O(N^3) FLOPs but O(N^3 / sqrt(M)) memory traffic
#define BS 64
void matmul_blocked(const float* A, const float* B, float* C, int N) {
    for (int ii = 0; ii < N; ii += BS)
     for (int jj = 0; jj < N; jj += BS)
      for (int kk = 0; kk < N; kk += BS)
       for (int i = ii; i < ii+BS; ++i)
        for (int j = jj; j < jj+BS; ++j) {
            float s = C[i*N+j];  // accumulate into C (must be zero-initialised)
            for (int k = kk; k < kk+BS; ++k) s += A[i*N+k] * B[k*N+j];
            C[i*N+j] = s;
        }
}

