// Address translation: strip KSEG bit, dispatch on top byte.
static inline uint8_t* host_ptr(uint32_t vaddr) {
  uint32_t paddr = vaddr & 0x1FFFFFFF;
  if (paddr < 0x00800000) return g_rdram + paddr;
  if (paddr - 0x04000000 < 0x1000) return g_dmem + (paddr - 0x04000000);
  if (paddr - 0x04001000 < 0x1000) return g_imem + (paddr - 0x04001000);
  if (paddr >= 0x10000000 && paddr < 0x10000000 + g_cart_size) return g_cart + (paddr - 0x10000000);
  return mmio_dispatch(paddr);  // VI/AI/PI/SI registers handled by callbacks
}

