static struct UcodeEntry {
  const char* name;
  uint8_t     sha256[32];
  void      (*hle_entry)(struct RCPCtx*);  // HLE handler
  void*     aot_module;                   // AOT-recompiled blob (NEON-native)
} g_ucode_table[] = {
  {"F3D",     {0xab,0xcd,...}, hle_f3d,     NULL},
  {"F3DEX",   {0x12,0x34,...}, hle_f3dex,   NULL},
  {"F3DEX2",  {0xff,0xee,...}, hle_f3dex2,  NULL},
  {"L3DEX2",  {0x99,0x88,...}, hle_l3dex2,  NULL},
  // ... ~25 known commercial ucode signatures plus a fallback LLE path
  {NULL,      {0},              NULL,        NULL},
};
void sp_task_start(struct OSTask_s* task) {
  uint8_t hash[32]; sha256(task->ucode, task->ucode_size, hash);
  for (auto& e: g_ucode_table) {
    if (e.name && memcmp(e.sha256, hash, 32) == 0) { e.hle_entry(rcp_ctx); return; }
  }
  // unknown ucode: AOT-compile MIPS+vector to NEON, cache, dispatch.
  void* mod = aot_recompile_rsp(task->ucode, task->ucode_size);
  call_native(mod, rcp_ctx);
}

