// Metal lowering: per-triangle draw call with translated combiner as fragment shader
// (Substrate-generated MSL.)
fragment float4 rdp_combiner(VOut in [[stage_in]],
                             texture2d<float> tex0 [[texture(0)]],
                             sampler bilinear  [[sampler(0)]],
                             constant CombinerUniforms& u [[buffer(0)]]) {
  float4 t0 = tex0.sample(bilinear, in.st_w.xy / in.st_w.z);
  float4 A  = select_input(u.combiner_A, in, t0, /*t1=*/t0, u.prim, u.env);
  float4 B  = select_input(u.combiner_B, in, t0, t0, u.prim, u.env);
  float4 C  = select_input(u.combiner_C, in, t0, t0, u.prim, u.env);
  float4 D  = select_input(u.combiner_D, in, t0, t0, u.prim, u.env);
  return (A - B) * C + D;   // exact RDP combiner formula
}

