# Forward (explicit) Euler
import numpy as np
def forward_euler(f, t0, y0, h, n_steps):
    t = t0; y = np.asarray(y0, float).copy()
    ts, ys = [t], [y.copy()]
    for _ in range(n_steps):
        y = y + h * f(t, y)        # y_{n+1} = y_n + h*f(t_n, y_n)
        t = t + h
        ts.append(t); ys.append(y.copy())
    return np.array(ts), np.array(ys)

# Forward Euler: O(h) global, 1 f-eval/step
import numpy as np
def euler(f, t0, y0, h, n_steps):
    t = t0; y = np.asarray(y0, float).copy()
    ys = [y.copy()]
    for _ in range(n_steps):
        y = y + h * f(t, y)
        t = t + h
        ys.append(y.copy())
    return np.array(ys)

