import numpy as np
from scipy.linalg import expm
def exp_stepping_kinetics(K, c0, h, n_steps):
    E = expm(h * K)                              # compute matrix exponential ONCE
    c = c0.copy(); cs = [c.copy()]
    for _ in range(n_steps):
        c = E @ c                                # exact propagation
        cs.append(c.copy())
    return np.array(cs)

