# Ad-hoc call-graph timing — manual nesting + log per function
import time, logging, threading
log = logging.getLogger(__name__)
_call_stack = threading.local()

def timed(fn):
    def wrapper(*a, **kw):
        stack = getattr(_call_stack, 'stack', [])
        parent = stack[-1] if stack else None
        stack.append(fn.__name__); _call_stack.stack = stack
        t0 = time.perf_counter()
        try:
            return fn(*a, **kw)
        finally:
            dt = time.perf_counter() - t0
            log.info('call name=%s parent=%s duration_ms=%.2f', fn.__name__, parent, dt*1000)
            stack.pop()
    return wrapper

