# Explicit stateful matcher that captures the first group, then verifies the
# next len(captured) characters equal it. Implements the backreference axiom
# directly: the captured substring is a runtime parameter consulted in a
# subsequent equality test.
def has_double(s):
    n = len(s)
    for start in range(n):
        # try every possible captured length k starting at 'start'
        max_k = (n - start) // 2
        for k in range(1, max_k + 1):
            captured = s[start:start+k]
            if not captured.isalnum() and '_' not in captured and not all(c.isalnum() or c == '_' for c in captured):
                continue
            # \w = [A-Za-z0-9_]
            if not all(c.isalnum() or c == '_' for c in captured):
                continue
            if s[start+k:start+2*k] == captured:
                return True
    return False

