import re
# Rule order matters: maximal munch + first-match-wins on ties.
RULES = [
    ('NUM',   re.compile(r'[0-9]+')),
    ('IDENT', re.compile(r'[A-Za-z_][A-Za-z0-9_]*')),
    ('PLUS',  re.compile(r'\+')),
    ('WS',    re.compile(r'\s+')),
]
def tokenize(s):
    i, out = 0, []
    while i < len(s):
        best = None
        for kind, pat in RULES:
            m = pat.match(s, i)
            if m and (best is None or m.end() > best[2]):
                best = (kind, m.start(), m.end())
        if best is None: raise SyntaxError(i)
        kind, j, k = best
        if kind != 'WS': out.append((kind, s[j:k]))
        i = k
    return out

