# Hand-written recursive descent (one function per nonterminal).
class P:
    def __init__(self, s): self.s, self.i = s, 0
    def peek(self): return self.s[self.i] if self.i < len(self.s) else ''
    def eat(self, c):
        if self.peek() == c: self.i += 1; return True
        return False
    def expr(self):
        n = self.term()
        while self.eat('+'):
            n = ('+', n, self.term())
        return n
    def term(self):
        n = self.factor()
        while self.eat('*'):
            n = ('*', n, self.factor())
        return n
    def factor(self):
        if self.peek().isdigit():
            j = self.i
            while self.peek().isdigit(): self.i += 1
            return int(self.s[j:self.i])
        if self.eat('('):
            n = self.expr()
            assert self.eat(')')
            return n
        raise SyntaxError('bad factor')
def parse(s):
    p = P(s); n = p.expr(); assert p.i == len(s); return n

# Pratt parser: left-binding-power table.
# led(op) consumes op and its right operand; nud(tok) consumes a leaf.
LBP = {'+':1, '-':1, '*':2, '/':2, '^':3}
RIGHT_ASSOC = {'^'}
class P:
    def __init__(self, toks): self.toks, self.i = toks, 0
    def peek(self): return self.toks[self.i] if self.i < len(self.toks) else None
    def advance(self): t = self.peek(); self.i += 1; return t
    def nud(self, t): return t  # leaves
    def led(self, left, op):
        rbp = LBP[op] - (1 if op in RIGHT_ASSOC else 0)
        right = self.expr(rbp)
        return (op, left, right)
    def expr(self, rbp):
        left = self.nud(self.advance())
        while self.peek() is not None and LBP.get(self.peek(), 0) > rbp:
            op = self.advance()
            left = self.led(left, op)
        return left
def parse(toks):
    p = P(toks); ast = p.expr(0)
    assert p.i == len(toks)
    return ast

