# Queue realised as two stacks (Knuth TAoCP vol 1 ex 2.2.1; Sedgewick).
class QueueViaTwoStacks:
    def __init__(self):
        self.in_stack  = []
        self.out_stack = []
    def enqueue(self, x):
        self.in_stack.append(x)
    def dequeue(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())   # reverse
        return self.out_stack.pop()
    def peek(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())
        return self.out_stack[-1]
    def is_empty(self):
        return not self.in_stack and not self.out_stack

