def f(values):
    # OOP tree: class hierarchy.
    class Node:
        def sum(self): raise NotImplementedError
    class Leaf(Node):
        def __init__(self, v): self.v = v
        def sum(self): return self.v
    class Branch(Node):
        def __init__(self, l, r): self.l = l; self.r = r
        def sum(self): return self.l.sum() + self.r.sum()
    # Build a left-leaning tree from values.
    tree = Leaf(values[0])
    for v in values[1:]:
        tree = Branch(tree, Leaf(v))
    return tree.sum()

