def f(values):
    # Rust enum modeled as tagged tuple: ("Leaf", v) | ("Branch", l, r).
    def make_leaf(v): return ("Leaf", v)
    def make_branch(l, r): return ("Branch", l, r)
    def sum_tree(node):
        tag = node[0]
        if tag == "Leaf":
            return node[1]
        if tag == "Branch":
            return sum_tree(node[1]) + sum_tree(node[2])
        raise ValueError(tag)
    tree = make_leaf(values[0])
    for v in values[1:]:
        tree = make_branch(tree, make_leaf(v))
    return sum_tree(tree)

