# Recursive tree walk — operation hard-wired into traverse
class Node:
    def __init__(self, value, children=()):
        self.value = value
        self.children = children

def sum_tree(node):
    s = node.value
    for c in node.children:
        s += sum_tree(c)
    return s

def print_tree(node, depth=0):
    print('  '*depth + str(node.value))
    for c in node.children:
        print_tree(c, depth+1)
# adding a new operation = adding a new function; tree shape ok, but operation logic duplicates traversal

