# Visitor pattern — traversal lives in node, operation lives in visitor
class Node:
    def accept(self, visitor):
        visitor.visit_pre(self)
        for c in self.children:
            c.accept(visitor)
        visitor.visit_post(self)

class SumVisitor:
    def __init__(self):
        self.total = 0
    def visit_pre(self, n):
        self.total += n.value
    def visit_post(self, n): pass

class PrintVisitor:
    def __init__(self):
        self.depth = 0
    def visit_pre(self, n):
        print('  '*self.depth + str(n.value))
        self.depth += 1
    def visit_post(self, n):
        self.depth -= 1

# new operation = new Visitor class; traversal logic written once

