import Foundation
#if canImport(CryptoKit)
import CryptoKit
let h = Insecure.MD5.hash(data: Data("hello".utf8))
print(h.map { String(format: "%02x", $0) }.joined())
#else
let p = Process(); p.launchPath = "/bin/sh"; p.arguments = ["-c", "printf hello | md5sum 2>/dev/null || printf hello | md5"]
let pipe = Pipe(); p.standardOutput = pipe; try? p.run(); p.waitUntilExit()
let data = pipe.fileHandleForReading.readDataToEndOfFile()
let s = String(data: data, encoding: .utf8) ?? ""
let h = s.filter { "0123456789abcdef".contains($0) }.prefix(32)
print(String(h))
#endif

