#include <stdio.h>
#include <ctype.h>
int main(void){
  FILE *p = popen("printf hello | md5sum 2>/dev/null || printf hello | md5", "r");
  if(!p) return 1;
  char buf[256]={0};
  if(!fgets(buf, sizeof(buf), p)){ pclose(p); return 1; }
  pclose(p);
  int n=0;
  for(int i=0; buf[i] && n<32; i++) if(isxdigit((unsigned char)buf[i])) { putchar(buf[i]); n++; }
  putchar('\n');
  return 0;
}

