// AVX2 SIMD: 8 int32 per instruction
#include <immintrin.h>
void add_simd(const int32_t* a, const int32_t* b, int32_t* c, size_t n) {
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        __m256i va = _mm256_load_si256((const __m256i*)(a + i));
        __m256i vb = _mm256_load_si256((const __m256i*)(b + i));
        __m256i vc = _mm256_add_epi32(va, vb);
        _mm256_store_si256((__m256i*)(c + i), vc);
    }
    for (; i < n; ++i) c[i] = a[i] + b[i];  // scalar tail
}

