// Blelloch up-sweep / down-sweep: O(2N) work, O(log N) depth — parallel-friendly
// (sketch; production uses SIMD shuffles or GPU warp shuffles)
void scan_par(int* a, int N) {
    // up-sweep: build reduction tree
    for (int d = 1; d < N; d *= 2)
        for (int i = d - 1; i + d < N; i += 2*d)
            a[i + d] += a[i];
    // down-sweep: propagate prefix
    a[N-1] = 0;
    for (int d = N/2; d >= 1; d /= 2)
        for (int i = d - 1; i + d < N; i += 2*d) {
            int t = a[i]; a[i] = a[i+d]; a[i+d] += t;
        }
    // (result is exclusive scan; add input for inclusive)
}

