# Bloom filter: m bits, k hash functions, O(m) memory regardless of |elements|
import mmh3
from bitarray import bitarray

class Bloom:
    def __init__(self, m, k):
        self.bits = bitarray(m); self.bits.setall(False)
        self.m, self.k = m, k
    def _ix(self, x):
        return [mmh3.hash(x, i) % self.m for i in range(self.k)]
    def add(self, x):
        for i in self._ix(x): self.bits[i] = True
    def __contains__(self, x):
        return all(self.bits[i] for i in self._ix(x))

seen = Bloom(m=1_000_000, k=7)   # ~1% FP at n=100k
